function legacyPanel(kind){document.exitPointerLock?.();const p=$('#panel');p.hidden=false;if(kind==='help'){p.innerHTML='<button class="close">Schließen ×</button><h2>Dein Weg nach oben</h2><p>WASD: laufen · Shift: sprinten<br>Maus ziehen oder klicken: Kamera<br>E: sammeln, trinken, füttern, reiten<br>Leertaste: springen / im Flug steigen<br>Strg / C: im Flug sinken<br>G: Gleiter öffnen · R: Falken rufen<br>F: absteigen (nahe am Boden)<br>I / Tab: Äther-Menü · K: Crafting · 1–8: Schnellplätze<br>Q: Beeren essen · Esc: Menü schließen</p><p>Betäube einen Falken, füttere ihn über sein Tierinventar und fertige einen Sattel an der Werkbank. Aufwinde (leuchtende Ringe) füllen seine Ausdauer auf. Dein Fortschritt wird lokal gespeichert.</p><button id="reset">Neue Expedition</button>';$('#reset').onclick=()=>{if(confirm('Gespeicherte Expedition löschen?')){localStorage.removeItem('skytamer-v1');location.reload()}}}else{p.innerHTML='<button class="close">Schließen ×</button><h2>'+ (kind==='craft'?'Handwerk':'Dein Himmelslager')+'</h2><p>'+(kind==='craft'?'Werkzeuge und Ausrüstung für deinen Aufstieg.':'Wähle ein Bauteil. Mit E auf dem grünen Raster vor dir platzieren. Bauen nur auf Inseln.')+'</p>';let items=kind==='craft'?[['axe','Steinaxt'],['saddle','Falkensattel']]:[['foundation','Holzfundament'],['wall','Holzwand'],['fire','Lagerfeuer'],['bed','Bett / Respawnpunkt']];for(let [id,name] of items){let b=document.createElement('button');b.textContent=name+' · '+Object.entries(costs[id]).map(([k,v])=>v+' '+labels[k]).join(', ');b.disabled=!afford(costs[id])||(kind==='craft'&&state[id]);b.onclick=()=>{if(kind==='craft')craft(id);else{buildMode=id;p.hidden=true;toast('E: platzieren · Esc: abbrechen')}};p.append(b)}}p.querySelector('.close').onclick=()=>{p.hidden=true;buildMode=null}}
