function showAetherItem(id){selectedItem=id;const el=$('#aetherItemDetail');if(!el)return;const item=ITEMS[id];el.innerHTML=`<strong>${itemIcon(id)} ${item.name}</strong><p>${item.desc}</p><div class="itemActions"></div>`;const actions=el.querySelector('.itemActions');function btn(text,fn,disabled=false){let b=document.createElement('button');b.textContent=text;b.disabled=disabled;b.onclick=fn;actions.append(b)}if(state.gear[id]&&item.damage)btn(state.equipped===id?'✓ In der Hand':'Ausrüsten',()=>{state.equipped=id;updateWeapon();save();panel('inventory')},state.equipped===id);if(['berry','cooked','bandage'].includes(id))btn('Benutzen',()=>useItem(id),!state.inv[id]);if(state.gear[id]&&state.durability[id]!==undefined)btn('Reparieren ('+Math.round(state.durability[id])+' %)',()=>repair(id),state.durability[id]>=100);let select=document.createElement('select');select.setAttribute('aria-label','Schnellplatz wählen');for(let n=0;n<8;n++){let opt=document.createElement('option');opt.value=n;opt.textContent='Schnellplatz '+(n+1);select.append(opt)}actions.append(select);btn('Belegen',()=>{state.hotbar[Number(select.value)]=id;toast('Schnellplatz '+(Number(select.value)+1)+' belegt.');save()})}
